            if len(df_a) < 60 or len(df_b) < 60:
                return

            ca = df_a["Close"].astype(float)
            cb = df_b["Close"].astype(float)

            # Align on common trading dates
            common = ca.index.intersection(cb.index)
            if len(common) < 50:
                return

