            # z-score the most recent value against that history.
            cut = max(30, int(len(spread) * 0.80))
            mu = float(np.mean(spread[:cut]))
            sig = float(np.std(spread[:cut]))
            if sig < 1e-8:
                return

            zscore = (spread[-1] - mu) / sig

